-- ── Little Rock (UAC, 16 players, coach Travis Ford) ──
insert into teams (name, conference, conf, head_coach, coach)
select 'Little Rock', 'UAC', 'UAC', 'Travis Ford', 'Travis Ford'
where not exists (select 1 from teams where name = 'Little Rock');
